package com.portfolio.assetory.payment.domain;
import java.math.BigDecimal; import java.time.LocalDateTime; import com.portfolio.assetory.order.domain.Order; import jakarta.persistence.*;
@Entity @Table(name="payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id",nullable=false,unique=true) private Order order; @Column(nullable=false,unique=true) private String transactionId; @Column(nullable=false) private String paymentMethod; @Column(nullable=false,precision=15,scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus status; private String failureReason; @Column(nullable=false) private LocalDateTime requestedAt; private LocalDateTime paidAt; @Column(nullable=false) private LocalDateTime updatedAt; protected Payment(){} public static Payment complete(Order order,boolean success){Payment p=new Payment();p.order=order;p.transactionId="MOCK-"+java.util.UUID.randomUUID();p.paymentMethod="MOCK";p.amount=order.getTotalAmount();p.status=success?PaymentStatus.SUCCESS:PaymentStatus.FAILED;p.requestedAt=LocalDateTime.now();p.updatedAt=p.requestedAt;if(success)p.paidAt=p.requestedAt;else p.failureReason="Mock 결제 실패";return p;} public Long getId(){return id;} public Order getOrder(){return order;} public BigDecimal getAmount(){return amount;} public PaymentStatus getStatus(){return status;} public LocalDateTime getPaidAt(){return paidAt;} }
